      'seed.Strength & Agility': 'Styrke & Agility',
      'seed.Goalkeeper Mobility Routine': 'Målmands-mobility',
      'seed.Interval Sprint Run': 'Intervalløb',
      'seed.Quick Feet Program': 'Hurtige ben',
